cat > ci_access.tf <<'EOF'
variable "github_repository" {
  type        = string
  description = "GitHub repository (owner/name) whose workflows may assume the CI roles. Only tokens issued for this repository match the role trust policies."
  default     = "platform/ingest"
}

variable "state_bucket" {
  type        = string
  description = "Name of the S3 bucket holding this configuration's remote state. The CI roles get access to the state and lock objects for the key in state_key only."
  default     = "ingest-terraform-state"
}

variable "state_key" {
  type        = string
  description = "Object key of this configuration's state file in the state bucket. The lock object is state_key with a .tflock suffix."
  default     = "ingest/terraform.tfstate"
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

# Plan role: assumed by pull_request runs. Read-only on the managed resources.
data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_repository}:pull_request"]
    }
  }
}

# Apply role: assumed only by runs on refs/heads/main.
data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_repository}:ref:refs/heads/main"]
    }
  }
}

data "aws_iam_policy_document" "state_access" {
  statement {
    sid       = "StateList"
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::${var.state_bucket}"]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = [var.state_key, "${var.state_key}.tflock"]
    }
  }

  statement {
    sid       = "StateRead"
    actions   = ["s3:GetObject"]
    resources = ["arn:aws:s3:::${var.state_bucket}/${var.state_key}"]
  }

  statement {
    sid       = "StateLock"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["arn:aws:s3:::${var.state_bucket}/${var.state_key}.tflock"]
  }
}

data "aws_iam_policy_document" "plan" {
  source_policy_documents = [data.aws_iam_policy_document.state_access.json]

  statement {
    sid = "ReadLanding"
    actions = [
      "s3:GetAccelerateConfiguration",
      "s3:GetBucketAcl",
      "s3:GetBucketCORS",
      "s3:GetBucketLocation",
      "s3:GetBucketLogging",
      "s3:GetBucketObjectLockConfiguration",
      "s3:GetBucketOwnershipControls",
      "s3:GetBucketPolicy",
      "s3:GetBucketPublicAccessBlock",
      "s3:GetBucketRequestPayment",
      "s3:GetBucketTagging",
      "s3:GetBucketVersioning",
      "s3:GetBucketWebsite",
      "s3:GetEncryptionConfiguration",
      "s3:GetLifecycleConfiguration",
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid = "ReadEvents"
    actions = [
      "sqs:GetQueueAttributes",
      "sqs:ListQueueTags",
    ]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ReadCheckpoints"
    actions = [
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTable",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }

  # These calls do not support resource-level permissions.
  statement {
    sid       = "ReadQueueLookup"
    actions   = ["sqs:ListQueues"]
    resources = ["*"]
  }
}

# Apply role gets the plan permissions plus write on the three managed resources.
# It holds no iam:* permissions, so it cannot change its own access.
data "aws_iam_policy_document" "apply" {
  source_policy_documents = [data.aws_iam_policy_document.plan.json]

  statement {
    sid = "WriteLanding"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:PutAccelerateConfiguration",
      "s3:PutBucketAcl",
      "s3:PutBucketCORS",
      "s3:PutBucketLogging",
      "s3:PutBucketOwnershipControls",
      "s3:PutBucketPolicy",
      "s3:PutBucketPublicAccessBlock",
      "s3:PutBucketRequestPayment",
      "s3:PutBucketTagging",
      "s3:PutBucketVersioning",
      "s3:PutEncryptionConfiguration",
      "s3:PutLifecycleConfiguration",
    ]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid = "WriteEvents"
    actions = [
      "sqs:DeleteQueue",
      "sqs:SetQueueAttributes",
      "sqs:TagQueue",
      "sqs:UntagQueue",
    ]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid       = "CreateEvents"
    actions   = ["sqs:CreateQueue"]
    resources = ["arn:aws:sqs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:ingest-events-*"]
  }

  statement {
    sid = "WriteCheckpoints"
    actions = [
      "dynamodb:CreateTable",
      "dynamodb:DeleteTable",
      "dynamodb:TagResource",
      "dynamodb:UntagResource",
      "dynamodb:UpdateContinuousBackups",
      "dynamodb:UpdateTable",
      "dynamodb:UpdateTimeToLive",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }
}

resource "aws_iam_role" "ci_plan" {
  name                 = "ingest-ci-plan"
  description          = "Assumed by pull_request runs of the ${var.github_repository} workflow to run terraform plan read-only."
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_plan" {
  name   = "terraform-plan"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.plan.json
}

resource "aws_iam_role" "ci_apply" {
  name                 = "ingest-ci-apply"
  description          = "Assumed by main-branch runs of the ${var.github_repository} workflow to run terraform apply."
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_apply" {
  name   = "terraform-apply"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.apply.json
}

output "ci_plan_role_arn" {
  description = "ARN of the read-only role for pull_request plan runs. Set it as the role-to-assume in the plan job."
  value       = aws_iam_role.ci_plan.arn
}

output "ci_apply_role_arn" {
  description = "ARN of the role for apply runs on main. Set it as the role-to-assume in the apply job."
  value       = aws_iam_role.ci_apply.arn
}
EOF
cat >> providers.tf <<'EOF'

variable "aws_region" {
  type        = string
  description = "AWS region the managed resources are created in, used to scope the CI apply role's queue creation permission."
  default     = "eu-north-1"
}

data "aws_caller_identity" "current" {}
EOF
sed -i 's/region = "eu-north-1"/region = var.aws_region/' providers.tf
terraform fmt -recursive -check -diff; which terraform tflint

